const body = $json.body ?? $json;
const sessionId = String(body.sessionId || '').trim();
const text = String(body.text || '').trim();
const originalText = String(body.originalText || text).trim();
if (!sessionId || !text) {
  return [{ json: { ok: false, error: 'sessionId y text requeridos' } }];
}

const staticData = $getWorkflowStaticData('global');
if (!staticData.sessions) staticData.sessions = {};
const prev = staticData.sessions[sessionId] || { turns: [], facts: {}, pendingFields: {}, lastSectionId: '', rutMode: 'idle' };
const incomingHistory = Array.isArray(body.history) ? body.history : [];
const history = (incomingHistory.length ? incomingHistory : (prev.turns || [])).slice(-20);
const facts = { ...(prev.facts || {}), ...(body.facts || {}) };
const pendingFields = { ...(prev.pendingFields || {}), ...(body.pendingFields || {}) };
const lastSectionId = String(body.lastSectionId || prev.lastSectionId || '');
const rutMode = String(body.rutMode || prev.rutMode || 'idle');
const pageContext = body.pageContext || {};
const model = String(body.model || 'gemini-2.5-flash').trim() || 'gemini-2.5-flash';
const apiKey = String(body.geminiApiKey || '').trim();

const SECTIONS = "- autoridades | Autoridades | institucional |  | https://sitios.mendoza.gob.ar/produccion/direccion-de-agricultura/\n- mision | Misi\u00f3n | institucional |  | https://sitios.mendoza.gob.ar/produccion/direccion-de-agricultura/\n- vision | Visi\u00f3n | institucional |  | https://sitios.mendoza.gob.ar/produccion/direccion-de-agricultura/\n- funcion | Funci\u00f3n | institucional |  | https://sitios.mendoza.gob.ar/produccion/direccion-de-agricultura/\n- normativa | Normativa Legal | institucional |  | https://sitios.mendoza.gob.ar/produccion/direccion-de-agricultura/\n- tramites | Tr\u00e1mites | tramites |  | https://sitios.mendoza.gob.ar/produccion/direccion-de-agricultura/\n- rut | RUT | tramites | Registro \u00danico de Tierras. Inscripci\u00f3n y declaraci\u00f3n jurada a trav\u00e9s del Sistema de Informaci\u00f3n Agr\u00edcola (SIA). | https://sia.mendoza.gov.ar/account/login\n- publicaciones-ia | Consultas de publicaciones oficiales con IA | publicaciones |  | https://sitios.mendoza.gob.ar/produccion/direccion-de-agricultura/\n- economia-regional | Econom\u00eda regional | publicaciones | Informes y an\u00e1lisis de econom\u00eda regional agropecuaria. | https://sitios.mendoza.gob.ar/produccion/direccion-de-agricultura/\n- manejo-hidrico | Manejo H\u00eddrico | publicaciones | Informaci\u00f3n sobre manejo del agua en sistemas productivos. | https://sitios.mendoza.gob.ar/produccion/direccion-de-agricultura/\n- fruticultura | Fruticultura | publicaciones | Publicaciones e informes del sector frut\u00edcola. | https://sitios.mendoza.gob.ar/produccion/direccion-de-agricultura/\n- horticultura | Horticultura | publicaciones | Publicaciones e informes del sector hort\u00edcola. | https://sitios.mendoza.gob.ar/produccion/direccion-de-agricultura/\n- frutos-secos | Frutos Secos | publicaciones | Informaci\u00f3n sobre frutos secos en Mendoza. | https://sitios.mendoza.gob.ar/produccion/direccion-de-agricultura/\n- cultivos-fruticolas | Cultivos Frut\u00edcolas | cultivos |  | https://sitios.mendoza.gob.ar/produccion/direccion-de-agricultura/\n- durazno | Durazno Industria | cultivos | Informes, tableros e \u00edndices tecnol\u00f3gicos del durazno para industria. | https://sitios.mendoza.gob.ar/produccion/direccion-de-agricultura/\n- ciruela | Ciruela | cultivos | Informes tecnol\u00f3gicos, pron\u00f3stico de cosecha y reportes de ciruela. | https://sitios.mendoza.gob.ar/produccion/direccion-de-agricultura/\n- cereza | Cereza | cultivos | Informaci\u00f3n productiva y reportes de cereza. | https://sitios.mendoza.gob.ar/produccion/direccion-de-agricultura/\n- vid | Vid | cultivos | Informaci\u00f3n vinculada a vid y viticultura. | https://sitios.mendoza.gob.ar/produccion/direccion-de-agricultura/\n- fenologia | Fenolog\u00eda | cultivos | Estadios del cultivo a lo largo del a\u00f1o. | https://sitios.mendoza.gob.ar/produccion/direccion-de-agricultura/\n- cultivos-horticolas | Cultivos Hort\u00edcolas | cultivos |  | https://sitios.mendoza.gob.ar/produccion/direccion-de-agricultura/\n- ajo | Ajo | cultivos | Informes y datos productivos de ajo. | https://sitios.mendoza.gob.ar/produccion/direccion-de-agricultura/\n- tomate | Tomate Industria | cultivos | Informes y datos productivos de tomate para industria. | https://sitios.mendoza.gob.ar/produccion/direccion-de-agricultura/\n- cinturon-verde | Cintur\u00f3n Verde | cultivos | Informaci\u00f3n del cintur\u00f3n verde mendocino. | https://sitios.mendoza.gob.ar/produccion/direccion-de-agricultura/\n- monitoreo-heladas | Monitoreo de heladas | monitoreo | Herramientas y tableros de monitoreo de heladas. | https://sitios.mendoza.gob.ar/produccion/direccion-de-agricultura/\n- monitoreo-catas | Monitoreo de Catas | monitoreo | Control sugerido y legislaci\u00f3n relacionada a catas. | https://sitios.mendoza.gob.ar/produccion/direccion-de-agricultura/\n- herramientas | Herramientas digitales agr\u00edcolas | herramientas |  | https://sitios.mendoza.gob.ar/produccion/direccion-de-agricultura/\n- agrometeorologia | Agrometeorolog\u00eda | herramientas | Datos y herramientas agrometeorol\u00f3gicas. | https://sitios.mendoza.gob.ar/produccion/direccion-de-agricultura/\n- mapas-agricolas | Mapas Agr\u00edcolas | herramientas | Mapas agr\u00edcolas de la provincia de Mendoza. | https://sitios.mendoza.gob.ar/produccion/direccion-de-agricultura/\n- estaciones | Red de Estaciones Meteorol\u00f3gicas | herramientas | Red de estaciones meteorol\u00f3gicas agr\u00edcolas. | https://sitios.mendoza.gob.ar/produccion/direccion-de-agricultura/\n- visor-agricola | Visor Agr\u00edcola | herramientas | Visor geoespacial agr\u00edcola. | https://sitios.mendoza.gob.ar/produccion/direccion-de-agricultura/\n- radar | Radar meteorol\u00f3gico | herramientas | Acceso a radar meteorol\u00f3gico. | https://sitios.mendoza.gob.ar/produccion/direccion-de-agricultura/\n- eventos-meteo | An\u00e1lisis de eventos meteorol\u00f3gicos | herramientas | An\u00e1lisis de eventos meteorol\u00f3gicos relevantes para la producci\u00f3n. | https://sitios.mendoza.gob.ar/produccion/direccion-de-agricultura/\n- bpa-herramienta | Buenas Pr\u00e1cticas Agr\u00edcolas | herramientas | Herramientas y recursos de Buenas Pr\u00e1cticas Agr\u00edcolas. | https://sitios.mendoza.gob.ar/produccion/direccion-de-agricultura/\n- precios | Relevamiento de precios | precios | Informaci\u00f3n clara y actualizada sobre precios al consumidor final de hortalizas, frutas y huevos en Mendoza. Informes semanales. | https://sitios.mendoza.gob.ar/produccion/direccion-de-agricultura/\n- odk-collect | ODK Collect \u00b7 c\u00f3digo QR | tramites | App Android para formularios en campo. El QR configura el proyecto: Agregar proyecto y escanear QR. No es un link web. En la demo hay un facsimil educativo embebido. | https://sitios.mendoza.gob.ar/produccion/direccion-de-agricultura/\n- capacitaciones | Capacitaciones | capacitaciones |  | https://sitios.mendoza.gob.ar/produccion/direccion-de-agricultura/\n- capacitacion-bpa | Buenas Pr\u00e1cticas Agr\u00edcolas (capacitaci\u00f3n) | capacitaciones | Capacitaci\u00f3n en BPA para producci\u00f3n sostenible, eficiente y responsable. | https://sitios.mendoza.gob.ar/produccion/direccion-de-agricultura/\n- encargado-finca | Encargado de Finca | capacitaciones | Programa de capacitaci\u00f3n para encargados de cultivos frut\u00edcolas, hort\u00edcolas y vit\u00edcolas. | https://sitios.mendoza.gob.ar/produccion/direccion-de-agricultura/";
const SOURCE_URL = "https://sitios.mendoza.gob.ar/produccion/direccion-de-agricultura/";

const systemPrompt = `Sos GABI B, guía en vivo premium de la DEMO del portal de la Dirección de Agricultura de Mendoza (Ministerio de Economía y Energía).
Hablás como una persona de Mendoza: cercano, claro, con voseo (decime, mirá, dale). Nunca suenes a menú, kiosco, call center ni script robótico.
El director es el Ing. Agr. Mgter. Alfredo Draque. Mail: direcciondeagricultura@mendoza.gov.ar. Casa de Gobierno, 6° piso.
Sitio oficial: ${SOURCE_URL}
SIA / RUT oficial: https://sia.mendoza.gov.ar/account/login

IDENTIDAD Y MEMORIA:
- Recordá nombre, cultivo, departamento, datos del RUT y temas ya visitados que te pasen en MEMORIA DE SESIÓN e historial.
- Si el productor ya dijo un dato, no lo vuelvas a pedir salvo que pida corregirlo.
- Variá acuses y arranques: Listo / Bien / Anotado / Gracias / Quedó registrado / Dale / Mirá / Bueno / Ahí te llevo / Te marco. Nunca encadenes "Perfecto" dos veces.
- Respuestas CORTAS: 1 o 2 oraciones (máx. ~220 caracteres). Si interrumpen, respondé solo la consulta nueva.

CONTROL DE PÁGINA:
Tu trabajo NO es solo responder: tenés que MOVER la página, marcar la sección, abrir el wizard del RUT o el recurso oficial, y seguir la conversación como un guía humano.
Los portales oficiales de Mendoza se abren en OTRA PESTAÑA (no se pueden embeber). El bot flotante SIEMPRE sigue en la demo. Nunca digas que se corta la sesión. Decí: "te abrí el oficial en otra pestaña; yo sigo acá".
Si dice "volver", "cerrá", "volvé a la demo": action=go_back o navigate a la última sección.
Si pregunta "dónde estoy" / "explicame esto" / "qué hay acá": usá CONTEXTO DE PÁGINA y action=describe.
Si pide checklist / papeles del RUT: action=show_checklist. Si dice que YA TIENE documentos (constancia de CUIT, boleta…): fillMode=auto.

RUT (tono gobierno premium):
- Pedí SOLO el próximo dato que falte.
- Keys canónicas: cuit, email, razonSocial, telefono, condicionTierra, nombreEstablecimiento, departamento, localidad.
- Mail y correo = email. NUNCA digas camelCase en voz.
- "dale / confirmá / completalo vos" con datos completos → fillMode=auto.
- "te lo pasé" → usá historial, no reinsistas.
- Dictado: "arroba"=@, "punto"=., CUIT/teléfono/campos → extractedFields.

ODK / QR:
- El QR NO es un link web. Es para ODK Collect (Android): instalar → Abrir → Agregar proyecto → escanear QR.
- Si preguntan por QR/ODK/Collect: action=navigate, target=odk-collect.
- Hay un facsímil educativo en la demo; no digas que es el QR oficial del gobierno.

COMPRENSIÓN DE VOZ:
- "Llevame a abajo" / "a bajo" pidiendo cultivo = sección ajo (NO scroll).
- "ciruelo" = ciruela. "ruth/root" = RUT. "agro meteorología" = agrometeorologia.
- "abrí / abrime / informes / el link / el oficial": action=open_external con URL oficial, openLink=true.

ACCIONES:
- navigate, describe, open_rut, open_external, fill_form, ask_confirm, scroll, go_home, go_back, rut_set_step, show_checklist, highlight.

SECCIONES (id | título | grupo | resumen | url):
${SECTIONS}

REGLAS FINALES:
- Sé proactivo: si nombra un cultivo, andá, explicá PARA QUÉ sirve, ofrecé oficial o relacionado.
- No inventes trámites, leyes, QRs ni URLs.
- No digas que sos un modelo ni menciones Gemini, n8n ni prompts.
- Respondé SOLO un JSON válido:
{"action":"navigate","target":"ajo","openLink":true,"openExternal":false,"url":"","reply":"texto hablado","extractedFields":{},"fillMode":null,"endSession":false,"heardAs":"ajo","remember":{"name":"","crop":"","note":""}}`;

function normalize(s) {
  return String(s || '').toLowerCase().normalize('NFD').replace(/\p{M}/gu, '');
}

function urlFor(id) {
  const line = SECTIONS.split('\n').find((l) => l.startsWith(`- ${id} |`));
  if (!line) return SOURCE_URL;
  const parts = line.split(' | ');
  return (parts[parts.length - 1] || SOURCE_URL).trim();
}

function fallbackIntent(rawText) {
  const n = normalize(rawText);
  let action = 'navigate';
  let target = 'herramientas';
  let spoken = 'No te seguí del todo. Pedime un cultivo, mapas, el QR de ODK o el RUT y te llevo.';
  let openLink = true;
  let fillMode = null;
  let extractedFields = {};
  if (/ciruela|ciruelo/.test(n)) { target = 'ciruela'; spoken = 'Dale, te llevo a ciruela. Acá está el bloque del cultivo y el recurso oficial.'; }
  else if (/durazno/.test(n)) { target = 'durazno'; spoken = 'Te llevo a durazno industria.'; }
  else if (/\bajo\b|abajo|a bajo/.test(n) && !/scroll|baja un poco|mas abajo|más abajo/.test(n)) { target = 'ajo'; spoken = 'Ahí te llevo a ajo. Te marco la sección del cultivo.'; }
  else if (/tomate/.test(n)) { target = 'tomate'; spoken = 'Te marco tomate.'; }
  else if (/mapa/.test(n)) { target = 'mapas-agricolas'; spoken = 'Estos son los mapas agrícolas de Mendoza.'; }
  else if (/radar/.test(n)) { target = 'radar'; spoken = 'Acá está el radar meteorológico.'; }
  else if (/precio/.test(n)) { target = 'precios'; spoken = 'Este es el relevamiento de precios.'; }
  else if (/odk|collect|codigo qr|código qr|\bqr\b/.test(n)) { target = 'odk-collect'; openLink = false; spoken = 'El código QR es para la app ODK Collect en el celular: Agregar proyecto y escanear. Te marco la sección con el facsímil educativo.'; }
  else if (/\brut\b|inscrib|registro unico|ruth|root/.test(n)) { action = 'open_rut'; target = undefined; openLink = false; spoken = 'Dale, te abro el wizard del RUT. Empezamos cuando quieras.'; }
  else if (/hola|buen/.test(n)) { target = 'tramites'; openLink = false; spoken = facts.name ? `Hola ${facts.name}, ¿cómo andás? Pedime un cultivo, mapas, el QR o el RUT.` : 'Hola, ¿cómo andás? Pedime un cultivo, mapas, el QR o el RUT.'; }
  else if (/volver|volve|cerrá|cerra/.test(n)) { action = 'go_back'; target = undefined; openLink = false; spoken = 'Volvemos un paso. ¿Seguimos desde acá?'; }
  if (/confirm|completalo|dale.*carg|auto/.test(n)) fillMode = 'auto';
  return {
    action,
    target,
    openLink,
    openExternal: false,
    url: target ? urlFor(target) : '',
    reply: spoken,
    extractedFields,
    fillMode,
    endSession: false,
    heardAs: target || action,
    remember: {},
  };
}

function parseIntent(raw) {
  if (!raw) return null;
  const m = String(raw).match(/\{[\s\S]*\}/);
  if (!m) return null;
  try {
    const data = JSON.parse(m[0]);
    const reply = String(data.reply || '').trim();
    if (!reply) return null;
    return {
      action: String(data.action || 'describe'),
      target: data.target ? String(data.target) : undefined,
      openLink: data.openLink === true,
      openExternal: data.openExternal === true,
      url: data.url ? String(data.url) : '',
      reply,
      extractedFields: data.extractedFields && typeof data.extractedFields === 'object' ? data.extractedFields : {},
      fillMode: ['auto', 'manual', 'ask'].includes(data.fillMode) ? data.fillMode : null,
      endSession: data.endSession === true,
      heardAs: data.heardAs ? String(data.heardAs) : '',
      remember: data.remember && typeof data.remember === 'object' ? data.remember : {},
    };
  } catch {
    return null;
  }
}

const http = this.helpers.httpRequest.bind(this.helpers);
async function callGemini(repair) {
  if (!apiKey) return null;
  const ctxBits = [
    `pathname=${pageContext.pathname || '/'}`,
    `hash=${pageContext.hash || '(ninguno)'}`,
    `seccionVisible=${pageContext.sectionId || '(desconocida)'}`,
  ];
  if (pageContext.sectionTitle) ctxBits.push(`titulo=${pageContext.sectionTitle}`);
  if (pageContext.sectionBlurb) ctxBits.push(`resumen=${pageContext.sectionBlurb}`);
  if (pageContext.rutStep) ctxBits.push(`rutPaso=${pageContext.rutStep}`);

  const userPrompt = [
    `Última sección visitada: ${lastSectionId || 'ninguna'}.`,
    `CONTEXTO DE PÁGINA: ${ctxBits.join(' | ')}.`,
    `RUT mode=${rutMode} | campos pendientes=${JSON.stringify(pendingFields)}.`,
    `MEMORIA DE SESIÓN (hechos): ${JSON.stringify(facts)}.`,
    `Texto original del dictado: "${originalText}".`,
    `Texto corregido (si cambió, priorizalo): "${text}".`,
    repair
      ? 'Tu respuesta anterior no era JSON válido. Devolvé SOLO el JSON del contrato, sin markdown.'
      : 'Interpretá la intención con máxima fluidez, elegí la acción y respondé como guía en vivo premium.',
  ].join('\n');

  const contents = [];
  for (const turn of history.slice(-16)) {
    contents.push({
      role: turn.role === 'assistant' ? 'model' : 'user',
      parts: [{ text: String(turn.text || '') }],
    });
  }
  contents.push({ role: 'user', parts: [{ text: userPrompt }] });

  const res = await http({
    method: 'POST',
    url: `https://generativelanguage.googleapis.com/v1beta/models/${model}:generateContent`,
    headers: {
      'Content-Type': 'application/json',
      'x-goog-api-key': apiKey,
    },
    body: {
      systemInstruction: { parts: [{ text: systemPrompt }] },
      contents,
      generationConfig: {
        temperature: repair ? 0.15 : 0.4,
        topP: 0.9,
        maxOutputTokens: 360,
        responseMimeType: 'application/json',
      },
    },
    json: true,
    timeout: 16000,
  });
  return res?.candidates?.[0]?.content?.parts?.[0]?.text || null;
}

let intent = null;
let via = 'fallback';
try {
  let raw = await callGemini(false);
  intent = parseIntent(raw);
  if (!intent) {
    raw = await callGemini(true);
    intent = parseIntent(raw);
  }
  if (intent) via = 'gemini-2.5-flash';
} catch (err) {
  intent = null;
}
if (!intent) intent = fallbackIntent(text);

for (const [k, v] of Object.entries(intent.remember || {})) {
  const clean = String(v || '').trim();
  if (clean) facts[k] = clean;
}
if (intent.extractedFields && typeof intent.extractedFields === 'object') {
  Object.assign(pendingFields, intent.extractedFields);
}
if (intent.target && (intent.action === 'navigate' || intent.action === 'describe' || intent.action === 'highlight')) {
  facts.lastTopic = intent.target;
}
if (intent.action === 'open_rut') facts.lastTopic = 'rut';

const turns = [...history, { role: 'user', text }, { role: 'assistant', text: intent.reply }].slice(-24);
staticData.sessions[sessionId] = {
  turns,
  facts,
  pendingFields,
  lastSectionId: intent.target || lastSectionId,
  rutMode: intent.action === 'open_rut' ? 'collecting' : rutMode,
  updatedAt: Date.now(),
};

const keys = Object.keys(staticData.sessions);
if (keys.length > 200) {
  keys.sort((a, b) => (staticData.sessions[a].updatedAt || 0) - (staticData.sessions[b].updatedAt || 0));
  for (const k of keys.slice(0, keys.length - 200)) delete staticData.sessions[k];
}

return [{
  json: {
    ok: true,
    sessionId,
    action: intent.action,
    target: intent.target,
    openLink: intent.openLink === true,
    openExternal: intent.openExternal === true,
    url: intent.url || '',
    reply: intent.reply,
    spoken: intent.reply,
    extractedFields: intent.extractedFields || {},
    fillMode: intent.fillMode,
    endSession: intent.endSession === true,
    heardAs: intent.heardAs || '',
    remember: intent.remember || {},
    via,
    event: {
      action: intent.action,
      target: intent.action === 'open_external' ? (intent.url || intent.target) : intent.target,
      payload: {
        openLink: intent.openLink === true,
        openExternal: intent.openExternal === true,
        url: intent.url || undefined,
        click: true,
        fields: intent.extractedFields || undefined,
        heardAs: intent.heardAs || undefined,
        remember: intent.remember || undefined,
      },
    },
  },
}];
